import { yupResolver } from "@hookform/resolvers/yup";
import { LoadingButton } from "@mui/lab";
import {
  Box,
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  FormLabel,
  Grid,
  IconButton,
  InputAdornment,
  Radio,
  RadioGroup,
  TextField,
  Typography,
} from "@mui/material";
import CloseIcon from "mdi-material-ui/Close";
import { useEffect, useState } from "react";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import { useParams } from "react-router-dom";

const validationSchema = yup.object().shape({
  feature: yup.string().trim().required("This field is required."),
  // .max(100, "This field requires at most 100 characters."),
  is_native_tools: yup.boolean(),
  is_plus: yup.boolean(),
});

const DialogOverviewFeatures = (props) => {
  const { mode, open, toggle, dataToEdit, onSuccess, overViewTableHeaderData } =
    props;
  const [loading, setLoading] = useState(false);
  const [dialogTitle, setDialogTitle] = useState("");

  const { id } = useParams();
  const {
    control,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm({
    defaultValues: {
      feature: "",
      is_native_tools: false,
      is_plus: false,
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    if (open) {
      setLoading(false);
      setDialogTitle(
        mode === "add"
          ? `Add Overview ${overViewTableHeaderData?.title_1}`
          : `Edit Overview ${overViewTableHeaderData?.title_1}`
      );
      reset({
        feature: dataToEdit?.feature || "",
        is_native_tools: dataToEdit?.is_native_tools || false,
        is_plus: dataToEdit?.is_plus || false,
      });
    }
  }, [dataToEdit, mode, open, reset]);

  const onSubmit = (data) => {
    let payload = {
      feature: data.feature,
      is_native_tools: data.is_native_tools,
      is_plus: data.is_plus,
      sub_it_solution_list_id: id,
    };

    setLoading(true);

    let apiInstance = null;

    if (mode === "edit") {
      apiInstance = axiosInstance.patch(
        ApiEndPoints.ITSolutionOverviewFeatures.edit(dataToEdit.id),
        payload,
        {}
      );
    } else {
      apiInstance = axiosInstance.post(
        ApiEndPoints.ITSolutionOverviewFeatures.create,
        payload,
        {}
      );
    }
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog open={open} fullWidth maxWidth="sm" scroll="paper">
        <DialogTitle
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <Box>{dialogTitle}</Box>
          <IconButton
            aria-label="close"
            onClick={toggle}
            sx={{ color: (theme) => theme.palette.grey[500] }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent
          sx={{ pb: 8, px: { sx: 8, sm: 15 }, pt: { xs: 8, sm: 12.5 } }}
        >
          <form id="hub-address-form" onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <FormControl fullWidth sx={{ mb: 4 }}>
                  <FormLabel
                    required
                    htmlFor="feature"
                    error={Boolean(errors.feature)}
                  >
                    {overViewTableHeaderData?.title_1}
                  </FormLabel>
                  <Controller
                    name="feature"
                    control={control}
                    render={({ field: { value, onChange } }) => (
                      <TextField
                        placeholder={`Enter ${
                          overViewTableHeaderData?.title_1 || ""
                        }`}
                        multiline
                        onChange={onChange}
                        id="feature"
                        value={value}
                        error={Boolean(errors.feature)}
                      />
                    )}
                  />
                  {errors.feature && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.feature.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Grid>

              <Grid item xs={6}>
                <Controller
                  name="is_native_tools"
                  control={control}
                  render={({ field: { onChange, value } }) => (
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={value}
                          onChange={(e) => onChange(e.target.checked)} // Update the value when checked state changes
                        />
                      }
                      label={overViewTableHeaderData?.title_2}
                    />
                  )}
                />
              </Grid>
              <Grid item xs={6}>
                {" "}
                <Controller
                  name="is_plus"
                  control={control}
                  render={({ field: { onChange, value } }) => (
                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={value}
                          onChange={(e) => onChange(e.target.checked)} // Update the value when checked state changes
                        />
                      }
                      label={overViewTableHeaderData?.title_3}
                    />
                  )}
                />
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions>
          <LoadingButton
            size="large"
            type="submit"
            form="hub-address-form"
            variant="contained"
            loading={loading}
          >
            Submit
          </LoadingButton>
          <Button size="large" variant="outlined" onClick={toggle}>
            Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default DialogOverviewFeatures;
